        {   return;
        }
        for (EntityType<?> entity : entities)
        {   ConfigSettings.ENTITY_TEMP_EFFECTS.get().put(entity, tempEffectsData);
        }
    });
}

package com.momosoftworks.coldsweat.data.codec.util;

import com.mojang.datafixers.util.Either;
